/**
 * The software a Valy machine is bought to run.
 *
 * Every mark here is the project's own, taken from Simple Icons (CC0) and
 * inlined as a single 24x24 path so the grid paints with the first frame — no
 * network request, no layout shift, no third-party host watching who reads the
 * homepage, which would be an odd thing on a page arguing for custody.
 *
 * Each row carries four colours, one pair per ground. `wash` is the cell fill — a trace of the
 * project's colour in paper, held light enough that the muted line beneath the
 * name clears 4.5:1. `brand` is the mark, darkened from the official value
 * only where it would otherwise fall below 3:1 against that wash; every
 * adjustment is noted at the value it replaces. Both are computed once, here,
 * so no component has to reason about contrast.
 *
 * Generated once and committed. Adding an app means adding a row here; nothing
 * else on the homepage needs to know.
 */

export type SelfHostedApp = {
  slug: string
  name: string
  /** What it stands in for, or what it does. Eight words at most. */
  line: string
  /** The project's own colour, dark enough to clear 3:1 on `wash`. */
  brand: string
  /** The cell fill: a trace of `brand` in paper, light enough for muted text. */
  wash: string
  /** The mark on the ink chapter, lightened until it clears 4:1 on `washDark`. */
  brandDark: string
  /** The cell fill on the ink chapter. */
  washDark: string
  /** Single-path 24x24 mark. */
  path: string
}

export type AppGroup = {
  id: string
  title: string
  blurb: string
  apps: SelfHostedApp[]
}

